import{_ as r,a8 as e,o as d,c as s,ah as l,K as a}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const f=JSON.parse('{"title":"WebNote-Workflow 架构决策：5 Agent 精简为主会话 + 3 subagent","description":"","frontmatter":{"type":"decision","scope":"webnote","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["WebNote","架构决策","subagent","工作流"]},"headers":[],"relativePath":"vault/Memory/Decisions/WebNote-Workflow架构决策-5Agent精简为主会话+3subagent.md","filePath":"vault/Memory/Decisions/WebNote-Workflow架构决策-5Agent精简为主会话+3subagent.md","lastUpdated":1789374053000}'),i={name:"vault/Memory/Decisions/WebNote-Workflow架构决策-5Agent精简为主会话+3subagent.md"};function b(g,t,h,c,u,_){const o=e("NolebaseGitContributors"),n=e("NolebaseGitChangelog");return d(),s("div",null,[t[0]||(t[0]=l('<h1 id="webnote-workflow-架构决策-5-agent-精简为主会话-3-subagent" tabindex="-1">WebNote-Workflow 架构决策：5 Agent 精简为主会话 + 3 subagent <a class="header-anchor" href="#webnote-workflow-架构决策-5-agent-精简为主会话-3-subagent" aria-label="Permalink to “WebNote-Workflow 架构决策：5 Agent 精简为主会话 + 3 subagent”">​</a></h1><blockquote><p>决策时间：2026-08-04（会话实测后确立）。此决策是后续 agent 定义文件化、skills 总编排等演进的起点。</p></blockquote><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>初版工作流把「采编 → 归类 → 提炼 → 核查 → 确认」拆成 <strong>5 个独立 Agent</strong>（采编/归类师/笔记匠/核查官/确认员），每个都是独立 AI 上下文。实测发现：很多步骤并不需要 AI——用 AI 做反而慢、贵，且引入额外幻觉风险（AI 可能猜错媒体格式、脑补提取失败原因、汇总时自作主张）。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p><strong>不是每一步都需要独立的 AI 上下文。</strong> 确定性的事主会话自己干，只有真正需要独立判断的才创建 subagent：</p><table tabindex="0"><thead><tr><th>步骤</th><th>处理方式</th><th>理由</th></tr></thead><tbody><tr><td>采编</td><td>❌ 主会话内化</td><td>URL 分类是正则匹配，文本提取是调 CLI 工具——确定性逻辑不需要 AI</td></tr><tr><td>归类师</td><td>✅ 独立 subagent</td><td>四选一语义分类需理解正文；归类判断不应影响笔记匠（认知污染）</td></tr><tr><td>笔记匠</td><td>✅ 独立 subagent</td><td>核心创作任务，需要完整上下文专注正文</td></tr><tr><td>核查官</td><td>✅ <strong>必须独立（不可妥协）</strong></td><td>安全闸门：笔记匠自己核查自己等于自检，查不出自己编的内容</td></tr><tr><td>确认</td><td>❌ 主会话内化</td><td>不读原文、不做新判断，只是汇总前三个产出 + 约束落地行为</td></tr></tbody></table><h2 id="效果" tabindex="-1">效果 <a class="header-anchor" href="#效果" aria-label="Permalink to “效果”">​</a></h2><ul><li>LLM 调用次数 5 → 3，节省 40%</li><li>消除采编、确认两个环节的幻觉风险（正则比 AI 更准）</li><li>输出文件仍为 5 个（<code>00-采编清单.md</code> ~ <code>04-待确认提案.md</code>），其中 00 和 04 由主会话直接产出</li></ul><h2 id="术语约定-2026-08-05-补充" tabindex="-1">术语约定（2026-08-05 补充） <a class="header-anchor" href="#术语约定-2026-08-05-补充" aria-label="Permalink to “术语约定（2026-08-05 补充）”">​</a></h2><p>「调度器」统一写作 <strong>「调度器（主会话）」</strong>——它不是一个 Agent，就是用户当前打开的 AI 会话本身（WorkBuddy/Codex/Claude Code 的当前对话）。若说&quot;调度器也是 Agent&quot;，会退化回 5 Agent 架构的理解。括号内场景（如「采编（调度器（主会话）自行执行）」）直接用「主会话」避免嵌套括号。</p><h2 id="判断标准-可复用到其他工作流" tabindex="-1">判断标准（可复用到其他工作流） <a class="header-anchor" href="#判断标准-可复用到其他工作流" aria-label="Permalink to “判断标准（可复用到其他工作流）”">​</a></h2><p>给一个步骤建独立 subagent 前先问两件事：</p><ol><li><strong>这步是确定性逻辑还是需要语义判断？</strong> 正则匹配、CLI 调用、格式汇总 → 主会话自己做（更准更快零幻觉）。</li><li><strong>这步的产出会被后续步骤信任吗？</strong> 若存在&quot;自己查自己&quot;或&quot;为证明自己判断正确而扭曲下游&quot;的风险 → 必须独立上下文。安全闸门类步骤（核查）不可妥协。</li></ol>',14)),a(o),a(n)])}const A=r(i,[["render",b]]);export{f as __pageData,A as default};
